   337	function labelTimeToMinute(labelTime: string): number | undefined {
   338	  const match = TIME_PATTERN.exec(labelTime);
   339	  if (!match) {
   340	    return undefined;
   341	  }
   342	
   343	  return Number(match[1]) * 60 + Number(match[2]);
