   346	function formatPlannerTime(labelTime: string): string {
   347	  const labelMinute = labelTimeToMinute(labelTime);
   348	  if (labelMinute === undefined) {
   349	    return labelTime;
   350	  }
   351	
   352	  const hour = Math.floor(labelMinute / 60);
   353	  const minute = labelMinute % 60;
   354	  const period = hour < 12 ? "AM" : "PM";
   355	  const twelveHour = hour % 12 || 12;
   356	
   357	  return `${twelveHour}:${minute.toString().padStart(2, "0")} ${period}`;
