 50	const getCurrentDeviceTime = (): Date => new Date();
 51	const LABEL_TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;
 52	const STORE_OPENING_MINUTE = 9 * 60;
 53	const STORE_CLOSING_MINUTE = 20 * 60;
 54	const CORRECTION_NAVIGATION_FAILURE_MESSAGE =
 55	  "Unable to open this correction. Try again.";
