 61	function getDeviceLabelTime(date: Date): LabelTime {
 62	  return {
 63	    labelDate: `${date.getFullYear()}-${padTimePart(date.getMonth() + 1)}-${padTimePart(date.getDate())}`,
 64	    labelTime: `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}`,
 65	  };
 66	}
 67	
 68	function labelTimeToMinute(labelTime: string): number | undefined {
 69	  const match = LABEL_TIME_PATTERN.exec(labelTime);
 70	  if (!match) {
 71	    return undefined;
 72	  }
 73	
 74	  return Number(match[1]) * 60 + Number(match[2]);
 75	}
 76	
 77	function isOutsideStoreHours(labelMinute: number | undefined): boolean {
 78	  return (
 79	    labelMinute !== undefined &&
 80	    (labelMinute < STORE_OPENING_MINUTE || labelMinute > STORE_CLOSING_MINUTE)
 81	  );
 82	}
