 84	function formatSavedLabelTime(sighting: Sighting): string {
 85	  const date = new Date(`${sighting.labelDate}T12:00:00`);
 86	  const hour = Math.floor(sighting.labelMinute / 60);
 87	  const minute = sighting.labelMinute % 60;
 88	  const time = new Intl.DateTimeFormat("en-US", {
 89	    hour: "numeric",
 90	    minute: "2-digit",
 91	  }).format(new Date(2000, 0, 1, hour, minute));
 92	  const formattedDate = new Intl.DateTimeFormat("en-US", {
 93	    day: "numeric",
 94	    month: "long",
 95	    year: "numeric",
 96	  }).format(date);
 97	
 98	  return `Saved label time for ${formattedDate} at ${time}.`;
 99	}
